update storage.buckets set public=false where id='event-photos';
create or replace function public.can_view_event_photo(p_event_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.events e where e.id=p_event_id and (e.owner_user_id=public.current_profile_id() or exists(select 1 from public.entries en join public.entry_players ep on ep.entry_id=en.id and ep.active join public.players p on p.id=ep.player_id where en.event_id=e.id and en.status<>'withdrawn' and p.linked_user_id=public.current_profile_id()))); $$;
revoke all on function public.can_view_event_photo(uuid) from public, anon; grant execute on function public.can_view_event_photo(uuid) to authenticated, service_role;
drop policy if exists qiudazi_photo_insert on storage.objects; create policy qiudazi_photo_insert on storage.objects for insert to authenticated with check (bucket_id='event-photos' and public.can_upload_photo(name));
drop policy if exists qiudazi_photo_read_own on storage.objects; drop policy if exists qiudazi_photo_read_event_member on storage.objects; create policy qiudazi_photo_read_event_member on storage.objects for select to authenticated using (bucket_id='event-photos' and array_length(storage.foldername(name),1)>=2 and (storage.foldername(name))[2] ~* '^[0-9a-f-]{36}$' and public.can_view_event_photo(((storage.foldername(name))[2])::uuid));
drop policy if exists qiudazi_photo_delete_own on storage.objects; create policy qiudazi_photo_delete_own on storage.objects for delete to authenticated using (bucket_id='event-photos' and public.can_upload_photo(name) and not exists(select 1 from public.event_photos ep where ep.original_url=storage.objects.name or ep.watermarked_url=storage.objects.name));
create or replace function public.list_my_event_photos() returns table(event_id uuid,event_name text,watermarked_url text,uploaded_at timestamptz,version integer) language sql stable security definer set search_path='' as $$ select e.id,e.name,p.watermarked_url,p.uploaded_at,p.version from public.events e join public.event_photos p on p.event_id=e.id where e.owner_user_id=public.current_profile_id() order by p.uploaded_at desc; $$; revoke all on function public.list_my_event_photos() from public, anon; grant execute on function public.list_my_event_photos() to authenticated, service_role;